p5.webserial:
// @receive led
let port;
let led = 0;

function setup() {
  createCanvas(440, 320);
  port = createSerial();
  port.selectPort(9600)
    .then(() => port.start());
}

function draw() {
  const line = port.readUntil("\n");
  if (line.trim()) led = Number(line);
  background(245);
  noStroke();
  fill(led ? "#ef6c68" : "#c9c9ce");
  circle(220, 140, 120);
  fill(45);
  textAlign(CENTER);
  textSize(22);
  text(led ? "LED ON" : "LED OFF", 220, 250);
}

arduino:
const int LED_PIN = 13;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(LED_PIN, HIGH);
  Serial.println(1);
  delay(500);
  digitalWrite(LED_PIN, LOW);
  Serial.println(0);
  delay(500);
}

